// Test to see what memoryview.obj actually contains
#include <Python.h>
#include <stdio.h>

// Define PyBUF_FULL_RO manually
#define PyBUF_FORMAT 0x0004
#define PyBUF_ND 0x0008
#define PyBUF_STRIDES (0x0010 | PyBUF_ND)
#define PyBUF_INDIRECT (0x0100 | PyBUF_STRIDES)
#define PyBUF_FULL_RO (PyBUF_INDIRECT | PyBUF_FORMAT)

static PyObject*
get_mv_obj(PyObject* self, PyObject* mv) {
    // Try to get the obj from the memoryview
    Py_buffer view;
    if (PyObject_GetBuffer(mv, &view, PyBUF_FULL_RO) < 0) {
        printf("Failed to get buffer from memoryview\n");
        return NULL;
    }

    printf("view.obj: %p\n", (void*)view.obj);
    if (view.obj) {
        printf("view.obj type: %s\n", Py_TYPE(view.obj)->tp_name);
        printf("view.obj refcount: %zd\n", Py_REFCNT(view.obj));
    }

    PyObject* obj = view.obj;
    Py_XINCREF(obj);  // Increment before releasing
    PyBuffer_Release(&view);

    return obj;  // Return the obj (with incremented refcount)
}

