{"command": "cat > /tmp/fix_patch.py << 'EOF'
# This script will create the fix for the memory leak

import re

# Read the file
with open('/testbed/cairo/surface.c', 'r') as f:
    content = f.read()

# 1. Add the Python 3 buffer protocol implementation after line 879 (image_surface_as_buffer)
# Find the location to add the Python 3 buffer functions
pattern = r'(static PyBufferProcs image_surface_as_buffer = \{[^}]+\};\n#endif)'

# The new Python 3 buffer functions
py3_buffer_funcs = '''
#if PY_MAJOR_VERSION >= 3
static int
image_surface_getbuffer (PyObject *obj, Py_buffer *view, int flags) {
  PycairoImageSurface *o = (PycairoImageSurface *)obj;
  cairo_surface_t *surface = o->surface;
  unsigned char *buffer;
  int height, stride;
  Py_ssize_t size;

  buffer = cairo_image_surface_get_data (surface);
  if (buffer == NULL) {
    PyErr_SetString(PyExc_ValueError, "surface has no data");
    return -1;
  }
  height = cairo_image_surface_get_height (surface);
  stride = cairo_image_surface_get_stride (surface);
  size = (Py_ssize_t)height * stride;

  return PyBuffer_FillInfo(view, obj, buffer, size, 0, flags);
}

static void
image_surface_releasebuffer (PyObject *obj, Py_buffer *view) {
  /* Nothing to do since we don't export any additional info */
}

static PyBufferProcs image_surface_as_buffer = {
  image_surface_getbuffer,
  image_surface_releasebuffer,
};
#endif
'''

# Replace the pattern
replacement = r'\1\n' + py3_buffer_funcs
content = re.sub(pattern, replacement, content)

# 2. Update the tp_as_buffer in PycairoImageSurface_Type for Python 3
# Find and replace the tp_as_buffer definition
old_tp_as_buffer = r'''#if PY_MAJOR_VERSION < 3
  &image_surface_as_buffer,           /\* tp_as_buffer \*/
#else
  0,                                  /\* tp_as_buffer \*/
#endif'''
new_tp_as_buffer = '''  &image_surface_as_buffer,           /* tp_as_buffer */'''
content = re.sub(old_tp_as_buffer, new_tp_as_buffer, content)

# 3. Update the get_data function to use PyMemoryView_FromObject
old_get_data = r'''static PyObject \*
image_surface_get_data \(PycairoImageSurface \*o\) \{
#if PY_MAJOR_VERSION >= 3
  Py_buffer view;
  cairo_surface_t \*surface;
  int height, stride;
  unsigned char \* buffer;

  surface = o->surface;
  buffer = cairo_image_surface_get_data \(surface\);
  if \(buffer == NULL\) \{
    Py_RETURN_NONE;
  \}
  height = cairo_image_surface_get_height \(surface\);
  stride = cairo_image_surface_get_stride \(surface\);
  if \(PyBuffer_FillInfo \(&view, \(PyObject \*\)o, buffer, height \* stride, 0, PyBUF_FULL\) < 0\)
    return NULL;

  return PyMemoryView_FromBuffer \(&view\);
#else
  return PyBuffer_FromReadWriteObject\(\(PyObject \*\)o, 0, Py_END_OF_BUFFER\);
#endif
\}'''

new_get_data = '''static PyObject *
image_surface_get_data (PycairoImageSurface *o) {
#if PY_MAJOR_VERSION >= 3
  return PyMemoryView_FromObject((PyObject *)o);
#else
  return PyBuffer_FromReadWriteObject((PyObject *)o, 0, Py_END_OF_BUFFER);
#endif
}'''

content = re.sub(old_get_data, new_get_data, content)

# Write the file
with open('/testbed/cairo/surface.c', 'w') as f:
    f.write(content)

print("Patch applied successfully!")
EOF
python /tmp/fix_patch.py"}

